  'onboarding': {
    'steps': {
      'welcome': { 'title': 'Welcome to StellarCred', 'summary': '...existing text...', 'tip': '...existing text...', 'railLabel': 'Welcome' },
      'connect-wallet': { 'title': 'Set up your wallet', 'summary': '...', 'tip': '...', 'railLabel': 'Wallet' },
      'get-credential': { 'title': 'Create your credential', 'summary': '...', 'tip': '...', 'railLabel': 'Credential' },
      'verify-trust': { 'title': 'Verify issuer trust', 'summary': '...', 'tip': '...', 'railLabel': 'Trust' },
      'generate-proof': { 'title': 'Generate a proof', 'summary': '...', 'tip': '...', 'railLabel': 'Proof' },
      'unlock': { 'title': "You're ready", 'summary': '...', 'tip': '...', 'railLabel': 'Finish' }
    },
    'trust': {
      'active': { 'label': 'Trusted', 'message': '...' },
      'key_retired': { 'label': 'Trusted (key retiring)', 'message': '...' },
      'key_revoked': { 'label': 'Key revoked', 'message': '...' },
